operation.add:
if ($this->user->hasPermission('access', 'extension/module/probg_services')) {
    $probg_services_children = array();

    if ($this->user->hasPermission('access', 'extension/probg_services/category')) {
        $probg_services_children[] = array(
            'name' => 'Categories',
            'href' => $this->url->link('extension/probg_services/category', 'user_token=' . $this->session->data['user_token'], true),
            'children' => array()
        );
    }

    $probg_services_children[] = array(
        'name' => 'Settings',
        'href' => $this->url->link('extension/module/probg_services', 'user_token=' . $this->session->data['user_token'], true),
        'children' => array()
    );

    $data['menus'][] = array(
        'id'       => 'menu-probg-services',
        'icon'     => 'fa-briefcase',
        'name'     => 'ProBG Services',
        'href'     => '',
        'children' => $probg_services_children
    );
}
